import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container for the node
  const root = new Group();

  // Plane geometry – use image aspect ratio if possible
  const imgUrl = config.imageUrl;
  const aspect = 1.6; // default fallback (512/320)
  const width = aspect;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ map: null, transparent: true });

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; apply when ready
  if (imgUrl) {
    ctx.textureLoader.loadTexture(imgUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      // store reference for cleanup
      plane.userData._texture = tex;
    });
  }

  // Apply cinematic primitives if any are listed
  const primitives = config.cinematicPrimitives ?? [];
  const activePrimitives = [];

  for (const prim of primitives) {
    const { name, params, trigger } = prim;
    if (typeof ctx.primitives[name] === 'function') {
      const instance = ctx.primitives[name](root, params);
      activePrimitives.push(instance);
    }
  }

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitives
    for (const p of activePrimitives) {
      if (p && typeof p.cleanup === 'function') {
        p.cleanup();
      }
    }
    // Dispose GSAP timelines if any were created (none in this node)
    gsap.globalTimeline.clear();

    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture
    const tex = plane.userData._texture;
    if (tex && typeof tex.dispose === 'function') {
      tex.dispose();
    }
  };

  return root;
}
